"""Base class and common data models for model adapters."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any
from pydantic import BaseModel, Field

from tinybench.config import GenerationConfig


class GenerationResult(BaseModel):
    """Output generated by a model backend for a single prompt."""
    text: str = Field(..., description="The raw generated text completion.")
    prompt_tokens: int | None = Field(default=None, description="Number of tokens in the input prompt.")
    generated_tokens: int | None = Field(default=None, description="Number of tokens generated.")
    latency_seconds: float = Field(..., description="Time taken to generate completion in seconds.")
    metadata: dict[str, Any] = Field(default_factory=dict, description="Backend-specific execution metadata.")


class ModelMetadata(BaseModel):
    """Metadata describing a model architecture, origin, and resource profile."""
    model_id: str = Field(..., description="Canonical model identifier or registry key.")
    model_name: str = Field(..., description="Human-readable model name.")
    family: str = Field(..., description="Model family (e.g. SmolLM2, Qwen2.5, Mock).")
    parameters: str = Field(..., description="Parameter count description (e.g. 135M, 0.5B).")
    license: str = Field(..., description="License identifier (e.g. Apache-2.0).")
    license_is_osi_approved: bool = Field(
        default=False,
        description="Whether this license is recognized by the Open Source Initiative (OSI).",
    )
    estimated_ram_mb: float = Field(..., description="Estimated RAM needed for CPU inference in MB.")
    backend_type: str = Field(..., description="Inference backend implementation type.")
    revision: str | None = Field(default=None, description="Model checkpoint commit hash or branch.")
    description: str = Field(..., description="Short explanation of model capabilities and architecture.")


class BaseModelAdapter(ABC):
    """Abstract interface for all TinyBench model inference backends."""

    def __init__(self, model_id: str, revision: str | None = None) -> None:
        self.model_id = model_id
        self.revision = revision
        self._is_loaded: bool = False

    @property
    def is_loaded(self) -> bool:
        """Check if model weights and tokenizer are currently loaded in memory."""
        return self._is_loaded

    @abstractmethod
    def load(self) -> float:
        """Load the model and tokenizer into memory.

        Returns:
            Initialization latency in seconds.
        """
        pass

    @abstractmethod
    def generate(self, prompt: str, config: GenerationConfig) -> GenerationResult:
        """Generate text completion for the provided prompt.

        Args:
            prompt: Text prompt to feed into the model.
            config: Generation sampling parameters.

        Returns:
            GenerationResult containing generated text and execution timing.
        """
        pass

    @abstractmethod
    def get_metadata(self) -> ModelMetadata:
        """Return model metadata, parameter counts, and estimated RAM requirements."""
        pass

    @abstractmethod
    def unload(self) -> None:
        """Release loaded model weights and free process memory."""
        pass
